# Surah Al-Qasas (chapter 28) — part 9: ayat 81-88 (IDs 3333-3340)
SURAH = 28

ENTRIES = {
3333: (
"پس ہم نے اسے اور اس کے گھر کو زمین میں دھنسا دیا — پس اس کے پاس اللہ کے سوا ایسی کوئی جماعت نہ تھی جو اس کی مدد کرتی — اور وہ اپنے کو بچانے والوں میں سے نہ تھا",
"""۱۔ قارون کا انجام — زمین میں دھنسنا؛ بے مدد۔
۲۔ ’’فَخَسَفْنَا بِهِ وَبِدَارِهِ الْأَرْضَ فَمَا كَانَ لَهُ مِن فِئَۃٍ يَنصُرُونَهُ مِن دُونِ اللَّهِ وَمَا كَانَ مِنَ الْمُنتَصِرِينَ‘‘ — پس ہم نے اسے اور اس کے گھر کو زمین میں دھنسا دیا — پس اس کے پاس اللہ کے سوا ایسی کوئی جماعت نہ تھی جو اس کی مدد کرتی — اور وہ اپنے کو بچانے والوں میں سے نہ تھا — یعنی پس ہم نے اسے اور اس کے گھر کو زمین میں دھنسا دیا پس اس کے پاس اللہ کے سوا ایسی کوئی جماعت نہ تھی جو اس کی مدد کرتی اور وہ اپنے کو بچانے والوں میں سے نہ تھا۔
۳۔ عملی سبق: دنیاوی دولت پر غرور نہ کرو؛ اللہ کی گرفت سے بچو؛ اس سے ڈرو۔"""
),
3334: (
"اور جن لوگ اس کی جگہ چاہتے تھے وہ صبح کہنے لگے افسوس اللہ ہی رزق وسعت دیتا ہے جس کے لیے چاہے یا تنگ کرتا ہے — اگر اللہ ہم پر احسان نہ فرماتا تو ہمیں دھنسا دیتا — افسوس کافر فلاح نہیں پاتے",
"""۱۔ قارون کا انجام — رزق کی وسعت و تنگی؛ اللہ کا احسان؛ کافروں کی ناکامی۔
۲۔ ’’وَأَصْبَحَ الَّذِينَ تَمَنَّوْا مَكَانَهُ بِالْأَمْسِ يَقُولُونَ وَيْكَأَنَّ اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ لَوْلَا أَن مَّنَّ اللَّهُ عَلَيْنَا لَخَسَفَ بِنَا وَيْكَأَنَّهُ لَا يُفْلِحُ الْكَافِرُونَ‘‘ — اور جن لوگ اس کی جگہ چاہتے تھے وہ صبح کہنے لگے افسوس اللہ ہی رزق وسعت دیتا ہے جس کے لیے چاہے یا تنگ کرتا ہے — اگر اللہ ہم پر احسان نہ فرماتا تو ہمیں دھنسا دیتا — افسوس کافر فلاح نہیں پاتے — یعنی اور جن لوگ اس کی جگہ چاہتے تھے وہ صبح کہنے لگے افسوس اللہ ہی رزق وسعت دیتا ہے جس کے لیے چاہے یا تنگ کرتا ہے اگر اللہ ہم پر احسان نہ فرماتا تو ہمیں دھنسا دیتا افسوس کافر فلاح نہیں پاتے۔
۳۔ عملی سبق: رزق کی وسعت و تنگی پر صبر کرو؛ اللہ کا شکر کرو؛ کافر نہ بنو۔"""
),
3335: (
"یہ آخرت کا گھر ہے — ہم اسے ان لوگوں کے لیے بناتے ہیں جو زمین میں تکبر اور فساد نہیں چاہتے — اور انجام متقین کا ہے",
"""۱۔ آخرت — تکبر و فساد سے پاک لوگ؛ متقین؛ اچھا انجام۔
۲۔ ’’تِلْكَ الدَّارُ الْآخِرَۃُ نَجْعَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُوًّا فِي الْأَرْضِ وَلَا فَسَادًا وَالْعَاقِبَۃُ لِلْمُتَّقِينَ‘‘ — یہ آخرت کا گھر ہے — ہم اسے ان لوگوں کے لیے بناتے ہیں جو زمین میں تکبر اور فساد نہیں چاہتے — اور انجام متقین کا ہے — یعنی یہ آخرت کا گھر ہے ہم اسے ان لوگوں کے لیے بناتے ہیں جو زمین میں تکبر اور فساد نہیں چاہتے اور انجام متقین کا ہے۔
۳۔ عملی سبق: تکبر اور فساد سے بچو؛ تقویٰ اختیار کرو؛ آخرت کی تیاری کرو۔"""
),
3336: (
"جو کوئی بھلائی لائے اسے اس سے بہتر ملے گا — اور جو کوئی برائی لائے تو برائیاں کرنے والوں کو صرف وہی بدلہ دیا جائے گا جو وہ کرتے تھے",
"""۱۔ جزا — بھلائی کا بہتر بدلہ؛ برائی کا عین بدلہ۔
۲۔ ’’مَن جَاءَ بِالْحَسَنَۃِ فَلَهُ خَيْرٌ مِّنْهَا وَمَن جَاءَ بِالسَّيِّئَۃِ فَلَا يُجْزَى الَّذِينَ عَمِلُوا السَّيِّئَاتِ إِلَّا مَا كَانُوا يَعْمَلُونَ‘‘ — جو کوئی بھلائی لائے اسے اس سے بہتر ملے گا — اور جو کوئی برائی لائے تو برائیاں کرنے والوں کو صرف وہی بدلہ دیا جائے گا جو وہ کرتے تھے — یعنی جو کوئی بھلائی لائے اسے اس سے بہتر ملے گا اور جو کوئی برائی لائے تو برائیاں کرنے والوں کو صرف وہی بدلہ دیا جائے گا جو وہ کرتے تھے۔
۳۔ عملی سبق: نیکیاں کماؤ؛ گناہوں سے بچو؛ اللہ کی جزا پر بھروسہ رکھو۔"""
),
3337: (
"بے شک جس نے تم پر قرآن کی پابندی لازم فرمائی وہ تمہیں وعدے کے دن پہنچانے والا ہے — کہہ دیجیے میرا رب زیادہ جانتا ہے کہ کون ہدایت لے کر آیا اور کون کھلی گمراہی میں ہے",
"""۱۔ نبی ﷺ — قرآن کی پابندی؛ مکہ لوٹنا؛ ہدایت بمقابلہ گمراہی۔
۲۔ ’’إِنَّ الَّذِي فَرَضَ عَلَيْكَ الْقُرْآنَ لَرَادُّكَ إِلَىٰ مَعَادٍ قُل رَّبِّي أَعْلَمُ مَن جَاءَ بِالْهُدَىٰ وَمَنْ هُوَ فِي ضَلَالٍ مُّبِينٍ‘‘ — بے شک جس نے تم پر قرآن کی پابندی لازم فرمائی وہ تمہیں وعدے کے دن پہنچانے والا ہے — کہہ دیجیے میرا رب زیادہ جانتا ہے کہ کون ہدایت لے کر آیا اور کون کھلی گمراہی میں ہے — یعنی بے شک جس نے تم پر قرآن کی پابندی لازم فرمائی وہ تمہیں وعدے کے دن پہنچانے والا ہے کہہ دیجیے میرا رب زیادہ جانتا ہے کہ کون ہدایت لے کر آیا اور کون کھلی گمراہی میں ہے۔
۳۔ عملی سبق: قرآن پر عمل کرو؛ ہدایت کی پیروی کرو؛ اللہ پر بھروسہ رکھو۔"""
),
3338: (
"اور تم امید نہیں کرتے تھے کہ تم پر کتاب نازل ہو گی — مگر یہ تمہارے رب کی رحمت ہے — پس تم ہرگز کافروں کے مددگار نہ بننا",
"""۱۔ رسول اللہ ﷺ — ناگہانی رحمت؛ کافروں کی مدد نہ کرنا۔
۲۔ ’’وَمَا كُنتَ تَرْجُو أَن يُلْقَىٰ إِلَيْكَ الْكِتَابُ إِلَّا رَحْمَۃً مِّن رَّبِّكَ فَلَا تَكُونَنَّ ظَهِيرًا لِّلْكَافِرِينَ‘‘ — اور تم امید نہیں کرتے تھے کہ تم پر کتاب نازل ہو گی — مگر یہ تمہارے رب کی رحمت ہے — پس تم ہرگز کافروں کے مددگار نہ بننا — یعنی اور تم امید نہیں کرتے تھے کہ تم پر کتاب نازل ہو گی مگر یہ تمہارے رب کی رحمت ہے پس تم ہرگز کافروں کے مددگار نہ بننا۔
۳۔ عملی سبق: اللہ کی رحمت پر شکر کرو؛ کافروں کا ساتھ نہ دو؛ حق پر قائم رہو۔"""
),
3339: (
"اور وہ تمہیں اللہ کی آیات سے نہ ہٹائیں جب کہ وہ تم پر نازل ہو چکی ہیں — اور اپنے رب کی طرف بلاؤ — اور مشرکین میں سے نہ بنو",
"""۱۔ نبی ﷺ — آیات سے ہٹانا؛ دعوت؛ مشرکین سے دوری۔
۲۔ ’’وَلَا يَصُدُّنَّكَ عَنْ آيَاتِ اللَّهِ بَعْدَ إِذْ أُنزِلَتْ إِلَيْكَ وَادْعُ إِلَىٰ رَبِّكَ وَلَا تَكُونَنَّ مِنَ الْمُشْرِكِينَ‘‘ — اور وہ تمہیں اللہ کی آیات سے نہ ہٹائیں جب کہ وہ تم پر نازل ہو چکی ہیں — اور اپنے رب کی طرف بلاؤ — اور مشرکین میں سے نہ بنو — یعنی اور وہ تمہیں اللہ کی آیات سے نہ ہٹائیں جب کہ وہ تم پر نازل ہو چکی ہیں اور اپنے رب کی طرف بلاؤ اور مشرکین میں سے نہ بنو۔
۳۔ عملی سبق: اللہ کی آیات پر قائم رہو؛ اس کی طرف بلاؤ؛ شرک سے بچو۔"""
),
3340: (
"اور اللہ کے ساتھ کسی اور معبود کو نہ پکارو — اس کے سوا کوئی معبود نہیں — ہر چیز ہلاک ہونے والی ہے سوائے اس کے چہرے کے — اسی کے لیے حکم ہے اور اسی کی طرف تم لوٹائے جاؤ گے",
"""۱۔ توحید — اللہ کے سوا کوئی معبود نہیں؛ فنا؛ حکم؛ لوٹنا۔
۲۔ ’’وَلَا تَدْعُ مَعَ اللَّهِ إِلَٰهًا آخَرَ لَا إِلَٰهَ إِلَّا هُوَ كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ لَهُ الْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ‘‘ — اور اللہ کے ساتھ کسی اور معبود کو نہ پکارو — اس کے سوا کوئی معبود نہیں — ہر چیز ہلاک ہونے والی ہے سوائے اس کے چہرے کے — اسی کے لیے حکم ہے اور اسی کی طرف تم لوٹائے جاؤ گے — یعنی اور اللہ کے ساتھ کسی اور معبود کو نہ پکارو اس کے سوا کوئی معبود نہیں ہر چیز ہلاک ہونے والی ہے سوائے اس کے چہرے کے اسی کے لیے حکم ہے اور اسی کی طرف تم لوٹائے جاؤ گے۔
۳۔ عملی سبق: صرف اللہ کو معبود مانو؛ فانی چیزوں پر بھروسہ نہ کرو؛ اس کی طرف رجو۔"""
),
}
